const css="*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#081a29;color:#eef3f8;font:15px/1.65 Inter,system-ui,-apple-system,sans-serif}a{color:#ebc77f}header,footer{background:#122538}header{border-bottom:1px solid #314356}.nav-shell,main,footer>div{max-width:1180px;margin:auto}nav{display:flex;align-items:center;gap:24px;padding:15px 24px}nav a{text-decoration:none}nav strong{margin-right:auto;line-height:1.1;letter-spacing:-.04em;font-size:23px;white-space:nowrap}nav strong a{color:#fff}nav strong b{color:#e6bf75}nav small{display:block;font-size:8px;letter-spacing:.2em;color:#d5dfeb;margin-top:5px}.nav-links{display:flex;align-items:center;gap:8px}.nav-links a{padding:9px 12px;border-radius:8px;color:#cad6e1;font-size:13px;font-weight:600;white-space:nowrap}.nav-links a[aria-current=page]{background:#e1bd7519;color:#f0d294}.login-link{border:1px solid #9a814e;border-radius:8px;padding:9px 13px;font-weight:700;font-size:12px;white-space:nowrap}main{padding:30px 24px 60px}h1,h2,h3{line-height:1.22;color:#fff;letter-spacing:-.025em}h1{font-size:clamp(1.85rem,4vw,3.1rem);margin:10px 0 14px;text-wrap:balance}h2{margin:27px 0 12px;font-size:1.3rem}p{max-width:75ch;color:#bdccd9;margin:10px 0 16px}.tag{color:#e8c785;font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.catalog-hero{text-align:center;position:relative;background:radial-gradient(ellipse at 50% 0%,#28435a,#13283a 58%,#102435);border:1px solid #33485b;border-radius:18px;padding:36px 22px 30px;margin-bottom:22px}.catalog-hero p{max-width:56ch;margin:0 auto 17px}.hero-count{display:inline-flex;align-items:center;gap:7px;border:1px solid #77663f;border-radius:30px;padding:5px 12px;color:#f1d39b;font-size:11px}.catalog-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0}.catalog-bar label{margin:0;flex:1;max-width:420px}.searchbox{display:flex;align-items:center;gap:8px;padding:0 12px;background:#122738;border:1px solid #34495b;border-radius:10px;color:#d0b57c}.searchbox input{max-width:none;margin:0;border:0;background:transparent;padding:12px 0;font-size:14px;min-width:0}.catalog-count{font-size:12px;color:#9eb2c3;white-space:nowrap}.filters{display:flex;flex-wrap:nowrap;overflow-x:auto;gap:7px;margin:0 0 18px;padding-bottom:5px}.filters button{flex-shrink:0}.filters button{padding:7px 12px;background:#14293a;border:1px solid #354a5a;border-radius:20px;font-size:12px;font-weight:600;color:#c5d1de}.filters button[aria-pressed=true]{background:#e5c27e;color:#14253b;border-color:#e5c27e}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card,form{background:linear-gradient(150deg,#172e40,#102435);border:1px solid #34495a;border-radius:14px;padding:18px;min-width:0}.card{display:flex;flex-direction:column;text-decoration:none;color:inherit;transition:border-color .18s,transform .18s}.card:hover{border-color:#c9a767;transform:translateY(-2px)}.card[hidden]{display:none!important}.card-top{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:11px}.card-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#e6c27b12;border:1px solid #846e4666;color:#e8c785;flex-shrink:0}.card-icon svg,.searchbox svg{width:20px;height:20px}.card h2{font-size:17px;line-height:1.3;margin:0 0 8px;color:#f7f9fb;overflow-wrap:anywhere}.card p{font-size:13px;line-height:1.5;margin:0 0 13px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;color:#b6c7d6}.card-action{margin-top:auto;color:#e9c582;font-size:12px;font-weight:700}.empty{padding:18px;color:#b7c8d6}.empty[hidden]{display:none}.related-heading{margin:30px 0 14px}.back{display:inline-flex;text-decoration:none;font-size:13px;margin-bottom:14px}.detail-hero{padding:24px;border:1px solid #34495b;background:radial-gradient(ellipse at 0 0,#233e53,#13283a);border-radius:16px;margin-bottom:22px}.detail-hero h1{margin-bottom:10px}.detail-hero p{margin-bottom:0}label{display:block;margin:12px 0;font-weight:600;font-size:14px}input{display:block;width:100%;padding:12px;border-radius:8px;border:1px solid #556577;background:#091b2a;color:white;font:inherit;margin-top:5px}button,.cta{display:inline-block;background:#e5c27e;color:#14253b;border:0;border-radius:9px;padding:12px 20px;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.cta-box{margin-top:28px;padding:23px;text-align:center;background:#14293b;border:1px solid #665738;border-radius:15px}.cta-box p{margin:0 auto 13px}output{display:block;margin-top:18px;background:#0b1f2f;border:1px solid #82683f;border-radius:10px;padding:16px;color:#f1d39b;font-weight:700;overflow-wrap:anywhere}form{max-width:720px}form button{width:100%;margin-top:8px}article{max-width:780px;margin:auto}article>p{font-size:16px;line-height:1.85}article h2{color:#eed39a;border-top:1px solid #334757;padding-top:22px}footer{padding:25px 24px}footer a{margin-right:14px;font-size:13px}footer p{font-size:12px;margin-bottom:0}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid #f4d28d;outline-offset:3px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){nav{padding:13px 16px;gap:10px;flex-wrap:wrap;justify-content:space-between}nav strong{font-size:21px;margin-right:0}.nav-links{order:3;width:100%;display:grid;grid-template-columns:1fr 1fr;gap:6px}.nav-links a{text-align:center;background:#0c1e2d;padding:8px 5px;font-size:12px}.login-link{padding:7px 10px;font-size:11px}main{padding:18px 14px 36px}.catalog-hero{padding:25px 14px 23px;margin-bottom:15px;border-radius:14px}.catalog-hero p{font-size:13px;line-height:1.55}.catalog-bar{margin:10px 0;gap:8px}.catalog-count{font-size:11px}.filters{gap:5px;margin-bottom:13px}.filters button{padding:6px 9px;font-size:11px}.grid{gap:9px}.blog-grid{grid-template-columns:1fr}.blog-grid .card{padding:13px 14px}.blog-grid .card-top{margin-bottom:8px}.blog-grid .card-icon{width:30px;height:30px}.blog-grid .card h2{font-size:16px}.blog-grid .card p{margin-bottom:8px;font-size:12px}.tools-grid .card{padding:12px 10px;min-height:164px}.tools-grid .card h2{font-size:14px}.tools-grid .card p{font-size:12px;-webkit-line-clamp:3}.tools-grid .card-top{margin-bottom:8px}.tools-grid .card-icon{width:34px;height:34px}.tools-grid .card .tag{font-size:8px;letter-spacing:.02em}.card-action{font-size:11px}.detail-hero{padding:18px}.detail-hero h1{font-size:1.8rem}article>p{font-size:15px}.cta-box{padding:18px}footer{padding:20px 14px}}@media(max-width:340px){.tools-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.card{transition:none}.card:hover{transform:none}}";
function layout(title,desc,path,body){return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' | Rota 40</title><meta name="description" content="'+esc(desc)+'"><meta name="robots" content="index,follow"><link rel="canonical" href="'+base+path+'"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(desc)+'"><meta property="og:type" content="website"><meta property="og:url" content="'+base+path+'"><style>'+css+'</style></head><body><header><nav><strong><a href="/">ROTA <b>40</b><small>BY EDUVERSO</small></a></strong><div class="nav-links"><a href="/blog"'+(path.startsWith('/blog')?' aria-current="page"':'')+'>Blog</a><a href="/ferramentas"'+(path.startsWith('/ferramentas')?' aria-current="page"':'')+'>Ferramentas gratuitas</a></div><a class="login-link" href="/login">Área do aluno</a></nav></header><main>'+body+'</main><footer><div><a href="/">Rota 40</a><a href="/blog">Blog</a><a href="/ferramentas">Ferramentas</a><p>Plataforma educacional independente, sem vínculo oficial com a OAB. Não constitui aconselhamento jurídico.</p></div></footer></body></html>'}
const links='<div class="cta-box"><h2>Transforme estudo em estratégia.</h2><p>Conheça a plataforma de preparação para a primeira fase da OAB.</p><a class="cta" href="/">Conheça o Rota 40 →</a></div>';
const glyphs=['M4 5h16v14H4z M8 9h8 M8 13h6','M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5','M3 12h18 M12 3v18 M4 4l3 3 M17 17l3 3','M3 3v18h18 M7 15l4-5 4 3 6-7','M12 3l9 5-9 5-9-5z M3 12l9 5 9-5','M4 4h16v16H4z M8 8h2 M14 8h2 M8 12h2 M14 12h2 M8 16h2 M14 16h2','M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2','M3 7h18 M6 3v4 M18 3v4 M4 7v14h16V7 M8 12h3 M13 12h3','M3 18h4v-6H3z M10 18h4V8h-4z M17 18h4V3h-4z','M3 6h18 M3 12h18 M3 18h18 M8 4v4 M16 10v4 M10 16v4'];
function icon(i){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+glyphs[i%glyphs.length]+'"/></svg>'}
const categories=[...new Set(articles.map(a=>a[2]))];
function articleCard(a){return '<a class="card" data-category="'+esc(a[2])+'" data-search="'+esc(a[1]+' '+a[2]+' '+a[3])+'" href="/blog/'+a[0]+'"><div class="card-top"><span class="card-icon">'+icon(categories.indexOf(a[2])%glyphs.length)+'</span><span class="tag">'+esc(a[2])+'</span></div><h2>'+esc(a[1])+'</h2><p>'+esc(a[3])+'</p><span class="card-action">Ler artigo →</span></a>'}
function toolCard(t){return '<a class="card" data-search="'+esc(t[1]+' '+t[2])+'" href="/ferramentas/'+t[0]+'"><div class="card-top"><span class="card-icon">'+icon(tools.indexOf(t))+'</span><span class="tag">Gratuito</span></div><h2>'+esc(t[1])+'</h2><p>'+esc(t[2])+'</p><span class="card-action">Usar ferramenta →</span></a>'}
const filterScript='<script>(()=>{const q=document.querySelector("#catalog-search"),cards=[...document.querySelectorAll(".catalog-grid .card")],buttons=[...document.querySelectorAll(".filters button")],count=document.querySelector(".catalog-count"),empty=document.querySelector(".empty");let category="";const norm=s=>s.normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLowerCase();function update(){const term=norm(q.value.trim());let n=0;cards.forEach(c=>{c.hidden=!(norm(c.dataset.search).includes(term)&&(!category||c.dataset.category===category));if(!c.hidden)n++});count.textContent=n+" de "+cards.length;empty.hidden=n!==0}q.addEventListener("input",update);buttons.forEach(b=>b.addEventListener("click",()=>{category=b.dataset.filter;buttons.forEach(x=>x.setAttribute("aria-pressed",String(x===b)));update()}));update()})();</script>';
function catalog(isBlog){const data=isBlog?articles:tools;const search='<div class="catalog-bar"><label class="searchbox"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><input id="catalog-search" type="search" aria-label="'+(isBlog?'Buscar artigos':'Buscar ferramentas')+'" placeholder="'+(isBlog?'Buscar artigos...':'Buscar ferramentas...')+'"></label><span class="catalog-count" aria-live="polite">'+data.length+' de '+data.length+'</span></div>';const filters=isBlog?'<div class="filters" aria-label="Categorias"><button type="button" data-filter="" aria-pressed="true">Todos</button>'+categories.map(c=>'<button type="button" data-filter="'+esc(c)+'" aria-pressed="false">'+esc(c)+'</button>').join('')+'</div>':'';return '<section class="catalog-hero"><span class="tag">'+(isBlog?'Biblioteca de estudos':'Recursos gratuitos')+'</span><h1>'+(isBlog?'Blog Rota 40':'Ferramentas para sua preparação')+'</h1><p>'+(isBlog?'Estratégias, métodos e guias para estudar com direção.':'Planeje suas metas, organize o tempo e acompanhe sua evolução. Sem cadastro.')+'</p><span class="hero-count">'+data.length+(isBlog?' artigos disponíveis':' ferramentas gratuitas')+'</span></section>'+search+filters+'<div class="grid catalog-grid '+(isBlog?'blog-grid':'tools-grid')+'">'+data.map(isBlog?articleCard:toolCard).join('')+'</div><p class="empty" hidden>Nenhum resultado encontrado. Tente outro termo.</p>'+links+filterScript}
function page(path){if(path==='/blog')return layout('Blog de preparação para a OAB','Guias de estudo, revisão e prática para a preparação para a OAB.',path,catalog(true));if(path==='/ferramentas')return layout('Ferramentas gratuitas de estudo para a OAB','Calculadoras e planejadores gratuitos para organizar sua preparação.',path,catalog(false));
const a=articles.find(a=>path==='/blog/'+a[0]);if(a)return layout(a[1],a[3],path,'<article><a class="back" href="/blog">← Voltar ao blog</a><div class="detail-hero"><p class="tag">'+esc(a[2])+'</p><h1>'+esc(a[1])+'</h1></div><h2>Por onde começar</h2><p>'+esc(a[3])+'</p><h2>Como aplicar na prática</h2><p>'+esc(a[4])+'</p><h2>Como avaliar sua evolução</h2><p>'+esc(a[5])+'</p><p>Conteúdo de orientação de estudos. Confira sempre o edital vigente no portal oficial do Exame de Ordem.</p><p><a href="/ferramentas">Experimente as ferramentas gratuitas</a></p>'+links+'</article><h2>Continue aprendendo</h2><div class="grid">'+articles.filter(x=>x!==a).sort((x,y)=>Number(y[2]===a[2])-Number(x[2]===a[2])).slice(0,3).map(articleCard).join('')+'</div>');
const t=tools.find(t=>path==='/ferramentas/'+t[0]);if(t){const fields=t[3].map((f,i)=>'<label>'+esc(f[0])+'<input type="number" required step="'+(t[4]==='horas'&&i===0?'0.25':'1')+'" min="'+f[2]+'" max="'+f[3]+'" value="'+f[1]+'"></label>').join('');const script='<script>const form=document.querySelector("form"),out=document.querySelector("output");form.addEventListener("submit",e=>{e.preventDefault();const [a,b,c,d]=Array.from(form.querySelectorAll("input"),x=>x.valueAsNumber);const fmt=x=>x.toLocaleString("pt-BR",{maximumFractionDigits:2});let result="";switch('+JSON.stringify(t[4])+'){case "acertos":result=a>b||c>b?"Acertos e meta não podem superar o total de questões.":fmt(a/b*100)+"% de acertos · "+Math.max(0,c-a)+" acertos até a meta.";break;case "horas":result=fmt(a*b)+" horas por semana · "+fmt(a*b*c)+" horas no período.";break;case "ritmo":result=fmt(b/a)+" minutos por questão · "+fmt(a/b*60)+" questões por hora.";break;case "meta":result=Math.ceil(a/b)+" questões por dia (meta arredondada para cima).";break;case "restante":result=b>a?"O tempo utilizado não pode exceder o total.":fmt(a-b)+" minutos restantes · "+fmt((a-b)/c)+" minutos por questão.";break;case "blocos":result=b+c>100?"A soma dos percentuais não pode exceder 100%.":"Teoria: "+fmt(a*b/100)+" min · Questões: "+fmt(a*c/100)+" min · Correção: "+fmt(a*(100-b-c)/100)+" min.";break;case "comparador":result=a>c||b>c?"Os acertos não podem superar o total.":fmt(a/c*100)+"% → "+fmt(b/c*100)+"% · Variação: "+fmt((b-a)/c*100)+" pontos percentuais.";break;case "dias":result=Math.ceil(a/b)+" dias de prática.";break;case "aderencia":result=fmt(a/b*100)+"% da meta de sessões · "+Math.max(0,b-a)+" sessões restantes.";break;case "ponderada":result=a>b||c>d?"Acertos não podem superar os totais.":fmt((a+c)/(b+d)*100)+"% de acertos combinados · "+(a+c)+" de "+(b+d)+" questões.";break;case "proporcoes":result=a>b||c>d?"Acertos não podem superar os totais.":fmt(a/b*100)+"% → "+fmt(c/d*100)+"% · Variação: "+fmt((c/d-a/b)*100)+" pontos percentuais.";break;case "seguros":result=b>a||a>c?"Confira os totais.":fmt((a-b)/c*100)+"% de acertos seguros · "+(a-b)+" acertos sem dúvida.";break;case "branco":result=b>a||c>a-b?"Confira os totais.":fmt(b/a*100)+"% em branco · "+(a-b===0?"Nenhuma questão respondida.":fmt(c/(a-b)*100)+"% de acertos entre respondidas.");break;case "correcao":result=fmt(a*b)+" min de resolução · "+fmt(a*c)+" min de correção · "+fmt(a*(b+c))+" min no total.";break;case "pomodoro":{const n=Math.floor((a+c)/(b+c));result=n+" blocos completos · "+n*b+" minutos de foco · "+Math.max(0,n-1)*c+" minutos de pausa.";break}case "reserva":result=fmt(a*b/100)+" horas de reserva · "+fmt(a*(100-b)/100)+" horas planejáveis.";break;case "fila":result=a===0?"Nenhuma revisão pendente.":b<=c?"A fila não diminui com esse ritmo.":Math.ceil(a/(b-c))+" dias, considerando entradas constantes.";break;case "erros":result=b>a?"Acertos não podem superar respostas.":(a-b)+" erros · "+fmt((a-b)/a*100)+"% de erro.";break;case "passagem":result=b>a?"Reserva não pode superar o tempo.":fmt(a-b)+" minutos de resolução · "+fmt((a-b)/c)+" minutos por questão · "+b+" minutos de revisão.";break;case "prioridade":result="Índice heurístico: "+fmt((100-a)*b/5)+" de 100. Quanto maior, maior a prioridade sugerida; não é peso oficial.";break;case "amostra":result=Math.max(0,b-a)+" questões para completar a amostra · "+fmt(a/b*100)+"% da meta.";break;case "metabloco":{const n=Math.max(0,Math.ceil((b+c)*d/100-a-1e-9));result=a>b?"Acertos não podem superar o total.":n>c?"A meta não é alcançável neste bloco: seriam necessários "+n+" acertos.":n+" acertos de "+c+" no próximo bloco · "+fmt(n/c*100)+"%.";break}case "horasdisc":result=fmt(a/b)+" horas por disciplina · "+fmt(a*60/b)+" minutos por disciplina.";break;case "equilibrio":{const n=a+b+c;result=n===0?"Informe algum tempo de estudo.":"Teoria: "+fmt(a/n*100)+"% · Prática: "+fmt(b/n*100)+"% · Correção: "+fmt(c/n*100)+"%.";break}case "cobertura":result=a>b?"Estudadas não podem superar o plano.":fmt(a/b*100)+"% de cobertura · "+(b-a)+" disciplinas restantes.";break;case "leitura":result=fmt(a*c/b)+" minutos estimados · "+fmt(a*c/b/60)+" horas.";break;case "cartoes":result=fmt(a*b/60)+" minutos estimados.";break;case "capacidade":result=Math.floor(a*60/b)+" cartões completos por sessão.";break;case "retencao":result=b>a?"Lembrados não podem superar revisados.":fmt(b/a*100)+"% recuperados sem consulta · "+(a-b)+" para revisar.";break;case "reincidencia":result=b>a?"Repetidos não podem superar revisitados.":fmt(b/a*100)+"% de reincidência.";break;case "recuperacao":result=b>a?"Corretos não podem superar revisitados.":fmt(b/a*100)+"% de recuperação · "+(a-b)+" ainda não resolvidos.";break;case "ritmoleitura":result=fmt(a/b*60)+" páginas por hora.";break;case "efetivo":result=b>a?"Interrupções não podem superar o tempo reservado.":(a-b)+" minutos efetivos · "+fmt((a-b)/a*100)+"% de aproveitamento do tempo.";break;case "saldo":result=fmt(b-a)+" horas de saldo · "+fmt(b/a*100)+"% da carga planejada.";break;case "atraso":{const n=Math.ceil(a/b);result=n+" min extras por dia · "+(n<=c?"Cabe na margem informada.":"Faltam "+(n-c)+" min de margem diária; reduza ou redistribua tarefas.");break}case "capquest":result=Math.floor(a/(b+c))+" questões com resolução e correção completas.";break;case "divquest":{const n=Math.floor(a/b),rem=a%b;result=(rem?rem+" blocos de "+(n+1)+" e ":"")+(b-rem)+" blocos de "+n+" questões"+(b>a?" (alguns blocos ficam vazios).":".");break}case "varritmo":result=fmt(b/a)+" → "+fmt(d/c)+" min por questão · Variação: "+fmt(d/c-b/a)+" min.";break;case "recpontos":result=a>b||c>b-a?"Confira o total e os erros disponíveis.":(a+c)+" acertos em cenário hipotético · "+fmt((a+c)/b*100)+"%.";break;case "progresso":result=a>b?"O número concluído não pode superar o total.":fmt(a/b*100)+"% concluído · "+(b-a)+" módulos restantes.";break}out.textContent=result;});form.requestSubmit();</script>';return layout(t[1],t[2],path,'<a class="back" href="/ferramentas">← Voltar às ferramentas</a><div class="detail-hero"><span class="tag">Ferramenta gratuita</span><h1>'+esc(t[1])+'</h1><p>'+esc(t[2])+'</p></div><form>'+fields+'<button type="submit">Calcular</button><output aria-live="polite"></output></form><p>Estimativa baseada exclusivamente nos dados informados. Não representa previsão de aprovação. Os dados não são enviados ao servidor.</p><p><a href="/blog">Leia nossos guias de estudo</a></p>'+links+script)}
return null}
function route(req,res,url){if(!['GET','HEAD'].includes(req.method))return false;const p=url.pathname;let body,type='text/html; charset=utf-8';if(p==='/robots.txt'){type='text/plain; charset=utf-8';body='User-agent: *\nDisallow: /app\nDisallow: /api/\nDisallow: /login\nDisallow: /cadastro\nDisallow: /auth/\nDisallow: /recuperar-senha\nDisallow: /redefinir-senha\nSitemap: '+base+'/sitemap.xml\n';}else if(p==='/sitemap.xml'){type='application/xml; charset=utf-8';body='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(x=>'<url><loc>'+base+x+'</loc></url>').join('')+'</urlset>'}else{body=page(p);if(body===null)return false}res.writeHead(200,{'Content-Type':type,'X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=300'});res.end(req.method==='HEAD'?undefined:body);return true}
module.exports={route,paths,page};
